{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "properties": {
        "name": {
            "type": "string",
            "minLength": 1,
            "maxLength": 255
        },
        "description": {
            "type": "string",
            "maxLength": 32767
        },
        "tags": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "key": {
                        "type": "string",
                        "pattern": "^[0-9a-zA-Z_-]{1,255}$"
                    },
                    "value": {
                        "type": "string",
                        "minLength": 1,
                        "maxLength": 255
                    }
                },
                "required": [
                    "key",
                    "value"
                ],
                "additionalProperties": false
            }
        },
        "attributes": {
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "name": {
                        "type": "string",
                        "pattern": "^[0-9a-zA-Z_-]{1,255}$"
                    },
                    "dataType": {
                        "type": "string",
                        "enum": [
                            "string",
                            "number",
                            "gps",
                            "boolean"
                        ]
                    }
                },
                "required": [
                    "name",
                    "dataType"
                ],
                "additionalProperties": false
            }
        },
        "deviceClass": {
            "type": "string",
            "enum": [
                "standalone",
                "master",
                "owned",
                "floating",
                "virtual"
            ]
        },
        "masterId": {
            "type": "string",
            "pattern": "^[A-Fa-f\\d]{24}$"
        }
    },
    "additionalProperties": false
}

