        "properties": {
            "standard": {
                "type": "string",
                "pattern": "^[a-zA-Z0-9_]*$",
                "description": "The BOLTS id of the standard"
            },
            "free": {
                "type": "object",
                "description": "Values for the free parameters"
            },
            "quantity": {
                "type": "number",
                "description": "Number of instances of this object",
                "default": 1
            },
            "optional": {
                "type": "boolean",
                "description": "If this object is strictly required",
                "default": false
            }
        },
        "required": [
            "standard"
        ],
        "additionalProperties": false
    },
    "name": {
        "type": "object",
        "description": "The information necessary for BOLTS to look up information about a name",
        "properties": {
            "name": {
                "type": "string",
                "pattern": "^[a-zA-Z0-9_]*$",
                "description": "The BOLTS id of the name"
            },
            "free": {
                "type": "object",
                "description": "Values for the free parameters"
            },
            "quantity": {
                "type": "number",
                "description": "Number of instances of this object",
                "default": 1
            },
            "optional": {
                "type": "boolean",
                "description": "If this object is strictly required",
                "default": false
            }
        },
        "required": [
            "name"
        ],
        "additionalProperties": false
    },
    "properties": {
        "bolts": {
            "$ref": "#/bolts"
        },
        "standard": {
            "$ref": "#/standard"
        },
        "name": {
            "$ref": "#/name"
        }
    },
    "required": [
        "bolts",
        "standard",
        "name"
    ]
}

